package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	fmt.Print("Tip percent? ")
	for scanner.Scan() {
		percent, err := strconv.Atoi(strings.TrimSpace(scanner.Text()))
		if err != nil {
			fmt.Println("That's not a whole number:", err)
			fmt.Print("Tip percent? ")
			continue
		}
		fmt.Println("Tip on a 40 bill:", 40*percent/100)
		break
	}
}

