// perVan works out how many parcels each van carries.
func perVan(parcels, vans int) int {
	return parcels / vans
}

func report(day string, parcels int, vansText string) {
	vans, _ := strconv.Atoi(vansText)
	fmt.Println(day+":", parcels, "parcels,", vans, "vans")
	fmt.Println("  each van:", perVan(parcels, vans))
}

func main() {
	fmt.Println("Weekly van report")
	report("Mon", 120, "4")
	report("Tue", 90, "3")
	report("Wed", 100, "five")
	report("Thu", 80, "2")
	fmt.Println("Report done")
}

