package main

import (
	"errors"
	"fmt"
	"strconv"
)

const limit = 30

// weigh reads a parcel's weight and checks that Scoot can carry it.
func weigh(text string) (int, error) {
	kg, err := strconv.Atoi(text)
	if err != nil {
		return 0, err
	}
	if kg <= 0 {
		return 0, errors.New("weight must be above zero")
	}
	if kg > limit {
		return 0, fmt.Errorf("too heavy: %d kg (limit %d kg)", kg, limit)
	}
	return kg, nil
}

func main() {
	fmt.Println(weigh("12"))
	fmt.Println(weigh("0"))
	fmt.Println(weigh("45"))
}

